        required_fields = ['api_key', 'model']

        for field in required_fields:
            if field not in self.config:
                raise ConfigValidationError(f"Missing required config field: {field}")

        if not self.config.get('api_key'):
            raise ConfigValidationError("API key cannot be empty")

        if not self.config.get('model'):
            raise ConfigValidationError("Model cannot be empty")

        # 验证API端点格式
        api_base = self.config.get('api_base', '')
        if api_base and not (api_base.startswith('http://') or api_base.startswith('https://')):
