class ConfigurationError(LLMClientError):
    """配置验证失败异常"""
    pass

class LLMClient:
    """LLM 客户端类"""

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self._validate_config()

    def _validate_config(self) -> None:
        """验证配置有效性"""
        required_fields = ['api_key', 'model']

        for field in required_fields:
            if field not in self.config or not self.config[field]:
                raise ConfigurationError(f"配置验证失败: 缺少必需字段 '{field}'")

        # 验证 API 密钥格式
        api_key = self.config.get('api_key', '')
        if not isinstance(api_key, str) or len(api_key) == 0:
            raise ConfigurationError("配置验证失败: api_key 无效")

        # 验证模型名称
        model = self.config.get('model', '')
        if not isinstance(model, str) or len(model) == 0:
            raise ConfigurationError("配置验证失败: model 无效")

        # 验证可选字段
        if 'base_url' in self.config:
            base_url = self.config['base_url']
            if not isinstance(base_url, str):
                raise ConfigurationError("配置验证失败: base_url 必须是字符串")

    def chat(
        self,
        messages: List[Dict[str, str]],
        temperature: float = 0.7,
        max_tokens: Optional[int] = None,
        **kwargs
    ) -> Dict[str, Any]:
        """
        发送聊天请求

        Args:
            messages: 消息列表，格式为 [{"role": "user", "content": "..."}]
            temperature: 温度参数
            max_tokens: 最大 token 数
            **kwargs: 其他参数

        Returns:
            响应结果

        Raises:
            ConfigurationError: 配置验证失败
            LLMClientError: 其他客户端错误
        """
        # 调用前再次验证配置，确保配置有效
        self._validate_config()

